/// Complete paired native configuration and selection observation. The caller
/// holds the final-admitted router guard; this helper never reads a new seal.
pub(crate) async fn coherent_observation(
    pinned: &ManifestPinnedSchemaDocument,
    sealed_identity: &str,
) -> anyhow::Result<(
    op_plugins::state_plugins::tched_router::TchedRouterState,
    Value,
)> {
    let contract = load_contract(pinned)?;
    let observation = TchedRouterRuntimeClient::from_env()
        .with_sealed_identity(Some(sealed_identity))
        .observe_config_and_state(&contract.secrets)
        .await?;
    validate_native_config(&contract, &observation.native_config)?;
    let paired = observation.into_state_and_fields()?;
    ensure_current_pin(&contract.schema_hash, &contract.schema_json).await?;
    Ok(paired)
}

/// Ordinary catalog selection always observes dashboard, independently of the
/// bridge's configurable default agent. Dedicated agents retain their facade.
pub(crate) async fn coherent_catalog_selection_observation(
    pinned: &ManifestPinnedSchemaDocument,
    sealed_identity: &str,
) -> anyhow::Result<Value> {
    let contract = load_contract(pinned)?;
    let observation = TchedRouterRuntimeClient::for_agent_alias("dashboard")
        .with_sealed_identity(Some(sealed_identity))
        .observe_config_and_state(&contract.secrets)
        .await?;
    validate_native_config(&contract, &observation.native_config)?;
    let (_, fields) = observation.into_state_and_fields()?;
    ensure_current_pin(&contract.schema_hash, &contract.schema_json).await?;
    Ok(fields)
}

async fn persist_tched_router_fields(
    &self,
    fields: &serde_json::Value,
    expected_schema_hash: String,
    actor_id: String,
) -> anyhow::Result<()> {
    anyhow::ensure!(
        fields.is_object(),
        "tched_router observed fields must be an object"
    );
    self.commit_state_update(
        StateChange {
            change_id: uuid::Uuid::new_v4().to_string(),
            event_id: 0,
            plugin_id: "tched_router".to_string(),
            object_path: op_plugins::canonical::plugin_path("tched_router"),
            change_type: ChangeType::PropertySet,
            member_name: None,
            old_value: None,
            new_value: simd_json::serde::to_owned_value(fields)?,
            tags_touched: Vec::new(),
            event_hash: String::new(),
            timestamp: chrono::Utc::now(),
            actor_id,
            source: ChangeSource::Internal,
        },
        Some(expected_schema_hash),
        true,
    )
    .await
    .map(|_| ())
}

pub(crate) async fn persist_tched_router_observation(
    &self,
    represented: &serde_json::Value,
    expected_schema_hash: &str,
) -> anyhow::Result<()> {
    let documents = op_plugins::state_plugins::runtime_documents::runtime_documents().await?;
    let methods =
        op_plugins::state_plugins::tched_router_legacy_methods::TchedRouterLegacyMethods::new(
            documents,
        );
    let (_, assignments) = methods.assignments().await?;
    let mut complete = represented.clone();
    let object = complete
        .as_object_mut()
        .context("tched_router runtime observation must be an object")?;
    object.insert(
        "model_assignments".into(),
        serde_json::to_value(assignments)?,
    );
    self.persist_tched_router_fields(
        &complete,
        expected_schema_hash.to_string(),
        "tched_router_selection".to_string(),
    )
    .await
    .map_err(|error| {
        anyhow::anyhow!(
            "tched_router native read completed but observation publication failed: {error}"
        )
    })
}

